function maxSumNonAdjacentK(a, K) {
  const n = a.length;
  const NEG = -1e15;
  // 1-based to align with recurrence
  const A = [0, ...a];
  let dpPrev = Array(K+1).fill(NEG), dpPrev2 = Array(K+1).fill(NEG), dpCur = Array(K+1).fill(NEG);
  dpPrev[0] = 0;
  if (n>=1) dpPrev2[0] = 0;
  for (let i=1;i<=n;i++){
    dpCur[0] = 0;
    for (let t=1;t<=K;t++){
      const pick = (i>=2 ? dpPrev2[t-1] : (t-1===0?0:NEG)) + A[i];
      const not = dpPrev[T];
      dpCur[t] = Math.max(not, pick);
    }
    dpPrev2 = dpPrev;
    dpPrev = dpCur;
    dpCur = Array(K+1).fill(NEG);
  }
  return dpPrev[K];
}
