## Why This Is Asked

This tests practical graph reasoning: counting shortest paths under a Dijkstra framework, handling path multiplicities without overflow, and edge-case ties.

## Key Concepts

- Dijkstra with path counting
- Tie handling on relaxation
- Complexity and edge-case handling

## Code Example

```javascript
function shortestPaths(graph, s, t) {
  const N = graph.length;
  const dist = Array(N).fill(Infinity);
  const ways = Array(N).fill(0);
  dist[s] = 0;
  ways[s] = 1;
  const pq = new MinHeap((a,b)=>a.d-b.d);
  pq.push({node:s, d:0});
  while (!pq.isEmpty()) {
     const {node:u, d} = pq.pop();
     if (d !== dist[u]) continue;
     for (const [v, w] of graph[u]) {
        const nd = dist[u] + w;
        if (nd < dist[v]) { dist[v] = nd; ways[v] = ways[u]; pq.push({node:v, d:nd}); }
        else if (nd === dist[v]) { ways[v] += ways[u]; }
     }
  }
  return { dist: dist[t], count: ways[t] };
}
```

## Follow-up Questions

- How would you apply modulo to prevent overflow for large counts?
- How would you adapt if edges had zero weight or negative cycles are possible?

## Why This Is Asked
Assesses augmenting a Trie to answer prefix-based queries with dynamic weights while maintaining efficient updates. Encourages careful handling of edge cases and update semantics.

## Key Concepts
- Trie augmentation with maxSubtreeWeight; non-decreasing weight updates.
- O(len(word)) insert and O(len(s)) query.
- Edge cases: empty word input, overlapping prefixes, no matches.

## Code Example
```javascript
class Node {
  constructor() {
    this.next = new Map();
    this.wordWeight = 0;
    this.hasWord = false;
    this.maxSubtreeWeight = 0;
  }
}
class PrefixWeightTrie {
  constructor() { this.root = new Node(); }
  insert(word, weight) {
    let node = this.root;
    for (const ch of word) {
      if (!node.next.has(ch)) node.next.set(ch, new Node());
      node = node.next.get(ch);
    }
    if (!node.hasWord || weight > node.wordWeight) {
      node.hasWord = true;
      node.wordWeight = weight;
    }
    // update maxSubtreeWeight along path (omitted detailed propagation for brevity)
  }
  queryLongestPrefix(s) {
    let node = this.root;
    let bestLen = 0, bestWeight = 0;
    for (let i = 0; i < s.length; i++) {
      const c = s[i];
      if (!node.next.has(c)) break;
      node = node.next.get(c);
      if (node.maxSubtreeWeight > 0) {
        bestLen = i + 1;
        bestWeight = node.maxSubtreeWeight;
      }
    }
    return [bestLen, bestWeight];
  }
}
```

## Why This Is Asked
This problem assesses mastery of graph algorithms on DAGs, including topological sorting, feasibility verification under ordered constraints, and shortest-path computation.

## Key Concepts
- Topological sort for DAGs
- DAG shortest-path DP (O(|V| + |E|))
- Feasibility checking with ordered mandatory edges
- Path reconstruction via predecessor pointers

## Code Example
```javascript
function shortestConstrainedPath(G, S, T, M) {
  const topo = topoSort(G);
  const idx = (v) => topo.indexOf(v);

  const canReach = (from, to) => {
    if (idx(from) >= idx(to)) return false;
    const reachable = new Set([from]);
    for (let i = idx(from); i < idx(to); i++) {
      for (const edge of G.adj[topo[i]]) {
        if (idx(edge.to) < idx(to)) reachable.add(edge.to);
      }
    }
    return reachable.has(to);
  };

  const points = [S, ...M.map(e => e[0]), ...M.map(e => e[1]), T];
  for (let i = 0; i < points.length - 1; i++) {
    if (!canReach(points[i], points[i + 1])) return null;
  }

  const segmentCost = (src, dst) => {
    const dist = {}; dist[src] = 0;
    for (let i = idx(src); i < idx(dst); i++) {
      const u = topo[i];
      for (const edge of G.adj[u]) {
        if (idx(edge.to) < idx(dst)) {
          if (dist[u] + edge.w < (dist[edge.to] ?? Infinity)) {
            dist[edge.to] = dist[u] + edge.w;
          }
        }
      }
    }
    return dist[dst];
  };

  let total = 0;
  const fullPath = [S];
  for (const [u, v, w] of M) {
    total += w;
    const seg = segmentCost(fullPath[fullPath.length - 1], u);
    if (seg === undefined) return null;
    total += seg;
  }
  const finalSeg = segmentCost(M[M.length - 1][1], T);
  if (finalSeg === undefined) return null;
  return total + finalSeg;
}
```

## Why This Is Asked
Tests designing an augmented state space and applying Dijkstra with a resource constraint.

## Key Concepts
- Dijkstra on expanded state space
- Edge relaxation with/without boost
- Path reconstruction from 3D predecessor structure

## Code Example
```javascript
function shortestWithBoosts(adj, s, t, K){
  const n = adj.length; const INF = 1e15;
  const dist = Array.from({length:n}, ()=>Array(K+1).fill(INF));
  const parent = Array.from({length:n}, ()=>Array(K+1).fill(null));
  dist[s][0] = 0;
  // min-heap assumed
  const pq = new MinHeap((a,b)=>a.d-b.d);
  pq.push({d:0,u:s,k:0});
  while(!pq.empty()){
    const {d,u,k} = pq.pop();
    if(d !== dist[u][k]) continue;
    for(const {to,w} of adj[u]){
      if(dist[to][k] > d + w){
        dist[to][k] = d+w; parent[to][k] = {u,k};
        pq.push({d: dist[to][k], u:to, k});
      }
      if(k < K){
        const ww = Math.floor(w/2);
        if(dist[to][k+1] > d + ww){
          dist[to][k+1] = d+ww; parent[to][k+1] = {u,k};
          pq.push({d: dist[to][k+1], u:to, k:k+1});
        }
      }
    }
  }
  let best = 0; for(let kk=1; kk<=K; kk++) if(dist[t][kk] < dist[t][best]) best = kk;
  return {dist: dist[t][best], used: best, parent};
}
```

## Follow-up Questions
- How would you adapt this for negative weights with a limited number of boosts? 
- How would you verify correctness on large graphs with high K?

## Why This Is Asked

This question probes practical Trie usage for autocomplete, encouraging explicit design choices and complexity reasoning.

## Key Concepts

- Trie node with 26-child array and isWord flag
- DFS enumeration in lexicographic order
- Edge cases: empty string, duplicates, limit handling, memory usage

## Code Example

```javascript
class TrieNode {
  constructor() { this.next = new Array(26).fill(null); this.isWord = false; }
}
class Trie {
  constructor() { this.root = new TrieNode(); }
  insert(w) { let p = this.root; for (const ch of w) { const i = ch.charCodeAt(0)-97; if (!p.next[i]) p.next[i] = new TrieNode(); p = p.next[i]; } p.isWord = true; }
  search(w) { let p = this.root; for (const ch of w) { const i = ch.charCodeAt(0)-97; if (!p.next[i]) return false; p = p.next[i]; } return p.isWord; }
  startsWith(pfx) { let p = this.root; for (const ch of pfx) { const i = ch.charCodeAt(0)-97; if (!p.next[i]) return false; p = p.next[i]; } return true; }
  listWithPrefix(pfx, limit) { const res = []; let p = this.root; for (const ch of pfx) { const i = ch.charCodeAt(0)-97; if (!p.next[i]) return res; p = p.next[i]; } const dfs = (node, prefix) => { if (res.length >= limit) return; if (node.isWord) res.push(prefix); for (let c = 0; c < 26; c++) { const child = node.next[c]; if (child) dfs(child, prefix + String.fromCharCode(97+c)); } }; dfs(p, pfx); return res; }
}
```

